import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, random, interpolate } from '../remotionShim';
import { Rect } from "@remotion/shapes";

{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }

// --- Sub-components ---

// 1. Background Stars
const StarBackground: React.FC<{
  count: number;
  speed: number;
}> = ({ count, speed }) => {
  const { width, height } = useVideoConfig();
  const frame = useCurrentFrame();

  const stars = useMemo(() => {
    return new Array(count).fill(true).map((_, i) => {
      const x = random(`star-x-${i}`) * width;
      const y = random(`star-y-${i}`) * height;
      const size = random(`star-size-${i}`) * 3 + 1;
      const opacity = random(`star-op-${i}`) * 0.5 + 0.3;
      return { x, y, size, opacity };
    });
  }, [count, width, height]);

  return (
    <AbsoluteFill>
      {stars.map((star, i) => {
        // Parallax movement
        const xPos = (star.x - frame * speed * (star.size * 0.1)) % width;
        const finalX = xPos < 0 ? width + xPos : xPos;

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: finalX,
              top: star.y,
              width: star.size,
              height: star.size,
              borderRadius: "50%",
              backgroundColor: "white",
              opacity: star.opacity,
            }}
          />
        );
      })}
    </AbsoluteFill>
  );
};

// 2. Card Graphic (Normal & Code variants)
const CardGraphic: React.FC<{
  mode: "normal" | "code";
  width: number;
  height: number;
  color: string;
  name: string;
  number: string;
}> = ({ mode, width, height, color, name, number }) => {
  const frame = useCurrentFrame();
  
  // -- Normal Mode --
  if (mode === "normal") {
    return (
      <div
        style={{
          width,
          height,
          borderRadius: 20,
          background: `linear-gradient(135deg, ${color}, ${color}88)`,
          position: "relative",
          overflow: "hidden",
          boxShadow: "0 10px 30px rgba(0,0,0,0.3)",
          display: "flex",
          flexDirection: "column",
          justifyContent: "space-between",
          padding: 24,
          border: "1px solid rgba(255,255,255,0.2)",
        }}
      >
        {/* Decorative Circles */}
        <div style={{ position: "absolute", top: -20, right: -20, opacity: 0.1 }}>
           <Rect width={150} height={150} fill="white" cornerRadius={75} />
        </div>
        <div style={{ position: "absolute", bottom: 40, left: 100, opacity: 0.1 }}>
           <Rect width={80} height={80} fill="white" cornerRadius={40} />
        </div>

        {/* Chip */}
        <div style={{ 
          width: 50, 
          height: 40, 
          background: "#e0e0e0", 
          borderRadius: 6,
          position: "relative",
          display: "flex",
          alignItems: "center",
          justifyContent: "center"
        }}>
           <div style={{ width: 40, height: 30, border: "1px solid #999", borderRadius: 4 }} />
           {/* Chip lines */}
           <div style={{ position: "absolute", width: "100%", height: 1, background: "#999", top: "50%"}} />
           <div style={{ position: "absolute", height: "100%", width: 1, background: "#999", left: "50%"}} />
        </div>

        {/* Text Details */}
        <div style={{ color: "white", fontFamily: "Inter", zIndex: 1 }}>
          <div style={{ fontSize: 18, fontWeight: 600, marginBottom: 8 }}>{name}</div>
          <div style={{ fontSize: 22, letterSpacing: 2, fontFamily: "monospace" }}>{number}</div>
        </div>
        
        {/* Visa-ish Logo */}
        <div style={{ position: "absolute", top: 24, right: 24, color: "white", fontWeight: 900, fontSize: 24, fontStyle: "italic", opacity: 0.9 }}>
          VISA
        </div>
      </div>
    );
  }

  // -- Code Mode --
  // Generate random matrix characters
  const rows = 8;
  const cols = 20;
  const charWidth = width / cols;
  const charHeight = height / rows;

  return (
    <div
      style={{
        width,
        height,
        borderRadius: 20,
        background: "#050505",
        position: "relative",
        overflow: "hidden",
        display: "flex",
        flexWrap: "wrap",
        alignContent: "flex-start",
        padding: 5,
        border: "1px solid rgba(0,255,100,0.3)",
      }}
    >
      {new Array(rows * cols).fill(0).map((_, i) => {
        // Deterministic flicker
        const flicker = random(`code-${i}-${Math.floor(frame / 5)}`) > 0.5;
        const char = random(`char-${i}`) > 0.5 ? "1" : "0";
        const isHighlight = random(`hl-${i}`) > 0.9;
        
        return (
          <div
            key={i}
            style={{
              width: charWidth,
              height: charHeight,
              color: isHighlight ? "#fff" : "#0f0",
              fontFamily: "Space Mono",
              fontSize: 14,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              opacity: flicker ? 1 : 0.5,
              textShadow: isHighlight ? "0 0 5px white" : "none"
            }}
          >
            {char}
          </div>
        );
      })}
    </div>
  );
};


// 3. Portal Card Wrapper
const PortalCard: React.FC<{
  x: number;
  y: number;
  width: number;
  height: number;
  screenCenter: number;
  color: string;
  name: string;
  number: string;
}> = ({ x, y, width, height, screenCenter, color, name, number }) => {

  // Logic: 
  // We render TWO cards at the same (x,y).
  // 1. Normal Card: clipped to show only the LEFT side of the portal.
  // 2. Code Card: clipped to show only the RIGHT side of the portal.
  
  // Calculate relative clip position
  // The line is at screenCenter.
  // The card is at x.
  // The cut line relative to card's left edge is: screenCenter - x.
  
  const cutLine = screenCenter - x;
  
  // Clip Path strings
  // Normal: Everything left of cutLine.
  // polygon(0 0, cutLine 0, cutLine 100%, 0 100%)
  const clipNormal = `polygon(0% 0%, ${cutLine}px 0%, ${cutLine}px 100%, 0% 100%)`;
  
  // Code: Everything right of cutLine.
  // polygon(cutLine 0, 100% 0, 100% 100%, cutLine 100%)
  const clipCode = `polygon(${cutLine}px 0%, 100% 0%, 100% 100%, ${cutLine}px 100%)`;

  return (
    <div style={{ position: "absolute", left: x, top: y, width, height }}>
      {/* Code Layer (Background) */}
      <div style={{ position: "absolute", top: 0, left: 0, clipPath: clipCode }}>
        <CardGraphic mode="code" width={width} height={height} color={color} name={name} number={number} />
      </div>

      {/* Normal Layer (Foreground) */}
      <div style={{ position: "absolute", top: 0, left: 0, clipPath: clipNormal }}>
        <CardGraphic mode="normal" width={width} height={height} color={color} name={name} number={number} />
      </div>
    </div>
  );
};



export type PortalCardScrollProps = Record<string, any>;

const PortalCardScroll: React.FC<PortalCardScrollProps> = ({
  backgroundColor = "#020010",
  transparentBackground = false,
  durationInSeconds = 10,
  scrollSpeed = 6,
  portalColor = "#00FFFF",
  cardColors = ["#8A2BE2", "#00FF7F", "#FF1493", "#4169E1"],
  cardScale = 1.0,
}) => {
  useFontLoader(["Inter", "Space Mono"]);
  const { width, height } = useVideoConfig();
  const frame = useCurrentFrame();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Card configuration
  const cardWidth = 400 * cardScale;
  const cardHeight = 250 * cardScale;
  const gap = 100 * cardScale;
  const totalItemWidth = cardWidth + gap;
  
  // Dummy data for cards
  const cardData = useMemo(() => [
    { name: "Emma Johnson", number: "4111 1111 1111 1111" },
    { name: "Liam Smith", number: "4222 2222 2222 2222" },
    { name: "Olivia Brown", number: "4333 3333 3333 3333" },
    { name: "Noah Davis", number: "4444 4444 4444 4444" },
    { name: "Ava Wilson", number: "4555 5555 5555 5555" },
  ], []);

  // Calculate infinite scroll positions
  // We want enough cards to cover the screen width + buffer
  // But strictly we just cycle through the colors provided
  const visibleCardsCount = Math.ceil(width / totalItemWidth) + 2;
  const totalCards = Math.max(visibleCardsCount, cardColors.length); // Ensure we have enough to cycle

  // Portal Line
  const portalX = width / 2;
  const glowSize = interpolate(Math.sin(frame * 0.1), [-1, 1], [10, 25]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden", fontFamily: "Inter" }}>
      
      {/* 1. Background Particles */}
      {!transparentBackground && <StarBackground count={150} speed={0.5} />}

      {/* 2. Scrolling Cards */}
      <AbsoluteFill style={{ alignItems: "center", justifyContent: "center" }}>
        {new Array(totalCards).fill(true).map((_, i) => {
          // Calculate X based on time
          // Initial Offset: start from right or just flow continuously
          const initialOffset = i * totalItemWidth;
          const movement = frame * scrollSpeed * 2; // Speed multiplier
          
          // Modulo logic for infinite loop
          // Position relative to "start"
          let rawX = (initialOffset + movement) % (totalCards * totalItemWidth);
          
          // Start off-screen left to create smooth loop entrance? 
          // Actually, we want them moving Left -> Right as per prompt
          // So x increases.
          // Wait, prompt says "scrolling horizontally from the left to the right".
          // So x should increase.
          
          // Let's adjust for centering vertically
          const y = height / 2 - cardHeight / 2;
          
          // Center the entire strip initially so at frame 0 it looks good?
          // Let's just let it flow.
          // We need to wrap around.
          // If x > width, it should wrap to -width?
          // Standard infinite scroll: x = (offset + time) % totalWidth.
          // If direction is L->R, we want x to go 0 -> width.
          
          // Let's shift so the loop is seamless
          // We render cards in a range that covers [-cardWidth, width]
          const cycleWidth = totalCards * totalItemWidth;
          let currentX = (initialOffset + movement) % cycleWidth;
          
          // Adjust to start from left side properly
          if (currentX > width + cardWidth) {
             currentX -= cycleWidth;
          }
          // Shift entire track to start slightly offscreen
          const startX = currentX - cardWidth; 

          // Color Cycle
          const color = cardColors[i % cardColors.length];
          const data = cardData[i % cardData.length];

          return (
            <PortalCard
              key={i}
              x={startX}
              y={y}
              width={cardWidth}
              height={cardHeight}
              screenCenter={portalX}
              color={color}
              name={data.name}
              number={data.number}
            />
          );
        })}
      </AbsoluteFill>

      {/* 3. Portal Line Overlay */}
      <div
        style={{
          position: "absolute",
          left: portalX,
          top: 0,
          bottom: 0,
          width: 4,
          backgroundColor: "#fff",
          transform: "translateX(-50%)",
          boxShadow: `0 0 ${glowSize}px ${glowSize / 2}px ${portalColor}, 0 0 ${glowSize * 2}px ${portalColor}`,
          zIndex: 10,
        }}
      />
      
      {/* Portal Particle Effects (Sparks at the line) */}
      {new Array(20).fill(true).map((_, i) => {
          const y = random(`spark-y-${i}`) * height;
          const speed = random(`spark-s-${i}`) * 5 + 2;
          const size = random(`spark-sz-${i}`) * 3;
          const offset = (frame * speed) % height;
          const finalY = (y + offset) % height;
          const distFromCenter = Math.abs(finalY - height / 2);
          const opacity = interpolate(distFromCenter, [0, height/2], [1, 0]);

          return (
              <div
                key={`spark-${i}`}
                style={{
                    position: "absolute",
                    left: portalX,
                    top: finalY,
                    width: size,
                    height: size,
                    backgroundColor: "white",
                    borderRadius: "50%",
                    transform: `translate(-50%, 0) scale(${Math.sin(frame * 0.2 + i)})`,
                    opacity: opacity * 0.8,
                    boxShadow: `0 0 5px ${portalColor}`,
                    zIndex: 11
                }}
              />
          )
      })}

    </AbsoluteFill>
  );
};

export default PortalCardScroll;